        { VALUES ?root { wd:Q21281182 wd:Q30938210 wd:Q114603616 wd:Q59164118 wd:Q460851 wd:Q375944 wd:Q111181355 wd:Q4782201 wd:Q126366236 wd:Q17012988 wd:Q4785038 wd:Q123965044 wd:Q635346 wd:Q126366632 wd:Q130575684 wd:Q121079 wd:Q121889130 wd:Q61991985 wd:Q125471256 wd:Q1936252 } ?item wdt:P31 ?root }
        UNION { VALUES ?root { wd:Q21281182 wd:Q30938210 wd:Q114603616 wd:Q59164118 wd:Q460851 wd:Q375944 wd:Q111181355 wd:Q4782201 wd:Q126366236 wd:Q17012988 wd:Q4785038 wd:Q123965044 wd:Q635346 wd:Q126366632 wd:Q130575684 wd:Q121079 wd:Q121889130 wd:Q61991985 wd:Q125471256 wd:Q1936252 } ?item wdt:P279 ?root }
        UNION { VALUES ?root { wd:Q21281182 wd:Q30938210 wd:Q114603616 wd:Q59164118 wd:Q460851 wd:Q375944 wd:Q111181355 wd:Q4782201 wd:Q126366236 wd:Q17012988 wd:Q4785038 wd:Q123965044 wd:Q635346 wd:Q126366632 wd:Q130575684 wd:Q121079 wd:Q121889130 wd:Q61991985 wd:Q125471256 wd:Q1936252 } BIND(?root AS ?item) }
        ?item rdfs:label ?en, ?zh.
        FILTER(LANG(?en)="en" && LANG(?zh) IN ("zh-hans", "zh-cn", "zh", "zh-tw", "zh-hant"))
        FILTER NOT EXISTS { ?item wdt:P31 wd:Q5 }
      } LIMIT 20000 }
      OPTIONAL { ?item schema:description ?description. FILTER(LANG(?description)="en") }
      OPTIONAL { ?item wdt:P31 ?kind }
    }
